$('#dialog-close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('sojang-music',1);r.onupgradeneeded=()=>r.result.createObjectStore('tracks',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function transaction(mode,action){return new Promise((resolve,reject)=>{const tx=db.transaction('tracks',mode);let request;try{request=action(tx.objectStore('tracks'))}catch(e){reject(e);return}tx.oncomplete=()=>resolve(request?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('저장이 취소됐습니다'))})}
async function persist(track){await transaction('readwrite',s=>s.put(track))}
function visible(){let list=tracks.filter(t=>(view!=='favorites'||t.favorite)&&(view!=='recent'||t.lastPlayed));const q=$('#search').value.trim().toLocaleLowerCase();if(q)list=list.filter(t=>(t.title+' '+t.artist).toLocaleLowerCase().includes(q));return list.sort((a,b)=>view==='recent'?(b.lastPlayed||0)-(a.lastPlayed||0):$('#sort').value==='name'?a.title.localeCompare(b.title,'ko'):b.added-a.added)}
function render(){const list=visible();$('#count').textContent=list.length;$('#side-count').textContent=tracks.length;$('#view-title').firstChild.textContent=({all:'내 음악 ',favorites:'좋아하는 곡 ',recent:'최근 들은 곡 '})[view];$$('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#collection-info').textContent=tracks.length?`${list.length}곡 · ${formatSize(list.reduce((a,t)=>a+(t.blob?.size||0),0))} · 기기에 보관 중`:'나의 작은 음악 보관함';$('#play-all').disabled=!list.length;$('#empty').hidden=list.length>0;$('#tracks').innerHTML=list.map((t,i)=>`<div class="track ${current?.id===t.id?'current':''}" data-id="${t.id}"><span class="track-num">${current?.id===t.id&&!audio.paused?'♫':String(i+1).padStart(2,'0')}</span><button class="track-art art-${t.color||'a'}" data-action="play" aria-label="${escapeHTML(t.title)} 재생">${t.cover?'':'♫'}</button><button class="track-info" data-action="play"><span class="track-title">${escapeHTML(t.title)}</span><span class="track-artist">${escapeHTML(t.artist)}${t.demo?' · 예시 음악':''}</span></button><span class="track-duration">${time(t.duration)}</span><button class="icon ${t.favorite?'liked':''}" data-action="like" aria-label="${escapeHTML(t.title)} 좋아요 ${t.favorite?'취소':'추가'}" aria-pressed="${!!t.favorite}">${t.favorite?'♥':'♡'}</button><button class="more" data-action="more" aria-label="${escapeHTML(t.title)} 관리">⋯</button></div>`).join('');list.forEach(t=>{if(t.cover){const node=$(`[data-id="${t.id}"] .track-art`);node.style.backgroundImage=`url("${t.cover}")`}});
if(!list.length){const filtered=tracks.length>0;$('#empty h3').textContent=filtered?(view==='favorites'?'좋아하는 곡을 모아보세요':view==='recent'?'아직 들은 음악이 없어요':'찾는 음악이 없어요'):'첫 번째 음악을 소장해 보세요';$('#empty p').textContent=filtered?(view==='favorites'?'곡 옆의 하트를 눌러 나만의 취향을 모아두세요.':view==='recent'?'음악을 재생하면 이곳에 차곡차곡 기록됩니다.':'다른 검색어를 입력하거나 새 곡을 추가해 보세요.'):'MP3, M4A, WAV 등 기기에서 재생 가능한 파일을 추가하세요.';$('#load-demo').hidden=tracks.some(t=>t.demo);}
updatePlayer()}
function formatSize(n){return n>1024*1024?`${(n/1024/1024).toFixed(1)} MB`:`${Math.round(n/1024)} KB`}
function updatePlayer(){const playing=!!current&&!audio.paused;$('#play').textContent=$('#mini-play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'일시정지':'재생');$('#mini-play').setAttribute('aria-label',playing?'일시정지':'재생');$('#now-title').textContent=current?.title||'당신의 음악을 기다려요';$('#now-artist').textContent=current?(current.artist+(current.demo?' · 예시 음악':'')):'첫 곡을 추가해 주세요';$('#mini-title').textContent=current?.title||'나만의 음악을 담아보세요';$('#mini-artist').textContent=current?.artist||'소장 · PERSONAL MUSIC';$('#now-like').disabled=!current;$('#now-like').textContent=current?.favorite?'♥':'♡';$('#now-like').classList.toggle('liked',!!current?.favorite);$('#now-like').setAttribute('aria-pressed',!!current?.favorite);$('#seek').disabled=!current||!Number.isFinite(audio.duration);const cover=$('#cover'),mini=$('#open-player');cover.className=`cover art-${current?.color||'a'}`;mini.className=`mini-art art-${current?.color||'a'}`;cover.style.backgroundImage=mini.style.backgroundImage=current?.cover?`url("${current.cover}")`:'';cover.style.backgroundSize='cover';cover.style.backgroundPosition='center';$$('#cover > div').forEach(el=>el.hidden=!!current?.cover);}
async function selectTrack(id,play=true){const track=tracks.find(t=>t.id===id);if(!track)return;const changed=current?.id!==id;if(changed){audio.pause();if(url)URL.revokeObjectURL(url);current=track;url=URL.createObjectURL(track.blob);audio.src=url;audio.load();$('#elapsed').textContent='0:00';$('#seek').value=0;$('#duration').textContent=time(track.duration);if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:track.title,artist:track.artist,album:'소장 · 나의 음악',artwork:[{src:track.cover||new URL('icon-512.png',location.href).href,sizes:'512x512',type:track.cover?'image/jpeg':'image/png'}]})}}render();if(play){try{await audio.play();track.lastPlayed=Date.now();await persist(track);render()}catch(e){if(e.name!=='AbortError')toast('재생할 수 없습니다. 파일 형식이나 기기 볼륨을 확인해 주세요.')}}}
