function advance(direction,automatic=false){let list=visible();if(!list.some(t=>t.id===current?.id))list=[...tracks].sort((a,b)=>b.added-a.added);if(!list.length)return;if(shuffle&&list.length>1){const options=list.filter(t=>t.id!==current?.id);selectTrack(options[Math.floor(Math.random()*options.length)].id);return}const i=list.findIndex(t=>t.id===current?.id),next=i+direction;if(automatic&&next>=list.length&&repeat==='off'){audio.currentTime=0;updatePlayer();return}selectTrack(list[(next+list.length)%list.length].id)}
async function toggleLike(t){if(!t)return;const value=!t.favorite;try{await persist({...t,favorite:value});t.favorite=value;render()}catch{toast('좋아요를 저장하지 못했습니다')}}
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$('#search').value='';render()});$('#search').oninput=render;$('#sort').onchange=render;
$('#tracks').onclick=e=>{const b=e.target.closest('[data-action]'),row=e.target.closest('[data-id]');if(!b||!row)return;const t=tracks.find(t=>t.id===row.dataset.id);if(b.dataset.action==='play')selectTrack(t.id);if(b.dataset.action==='like')toggleLike(t);if(b.dataset.action==='more')manageTrack(t)};
$('#play').onclick=$('#mini-play').onclick=togglePlay;$('#next').onclick=$('#mini-next').onclick=()=>advance(1);$('#previous').onclick=()=>{if(audio.currentTime>3)audio.currentTime=0;else advance(-1)};$('#now-like').onclick=()=>toggleLike(current);$('#play-all').onclick=()=>{const list=visible();if(list.length)selectTrack(list[0].id)};
$('#shuffle').onclick=()=>{shuffle=!shuffle;$('#shuffle').classList.toggle('enabled',shuffle);$('#shuffle').setAttribute('aria-pressed',shuffle);$('#shuffle').setAttribute('aria-label',shuffle?'셔플 켜짐':'셔플 꺼짐');toast(shuffle?'순서를 섞어서 재생합니다':'순서대로 재생합니다')};
$('#repeat').onclick=()=>{repeat=repeat==='off'?'all':repeat==='all'?'one':'off';$('#repeat').classList.toggle('enabled',repeat!=='off');$('#repeat').textContent=repeat==='one'?'↻₁':'↻';$('#repeat').setAttribute('aria-pressed',repeat!=='off');$('#repeat').setAttribute('aria-label',({off:'반복 꺼짐',all:'전체 반복',one:'한 곡 반복'})[repeat]);toast(({off:'반복 재생을 껐습니다',all:'보관함 전체를 반복합니다',one:'현재 곡을 반복합니다'})[repeat])};
$('#seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)*audio.duration/100};audio.volume=.8;$('#volume').oninput=e=>{audio.volume=Number(e.target.value);$('#volume-value').textContent=`${Math.round(audio.volume*100)}%`};audio.ontimeupdate=()=>{$('#elapsed').textContent=time(audio.currentTime);$('#seek').value=audio.duration?audio.currentTime/audio.duration*100:0};audio.onloadedmetadata=()=>{$('#duration').textContent=time(audio.duration);$('#seek').disabled=!Number.isFinite(audio.duration);if(current&&Number.isFinite(audio.duration)&&Math.abs((current.duration||0)-audio.duration)>.5){current.duration=audio.duration;persist(current).then(render).catch(()=>{})}};audio.onplay=audio.onpause=()=>{updatePlayer();render()};audio.onended=()=>{if(repeat==='one'){audio.currentTime=0;audio.play().catch(()=>toast('재생 버튼을 눌러 주세요'))}else advance(1,true)};audio.onerror=()=>{if(current)toast('이 기기에서 재생할 수 없는 파일입니다. MP3 또는 M4A로 다시 시도해 주세요.')};
function metadata(file){return new Promise(resolve=>{const a=new Audio(),u=URL.createObjectURL(file);const finish=()=>{clearTimeout(timer);const duration=Number.isFinite(a.duration)?a.duration:0;a.removeAttribute('src');a.load();URL.revokeObjectURL(u);resolve(duration)};const timer=setTimeout(finish,5000);a.onloadedmetadata=a.onerror=finish;a.src=u})}
async function importFiles(files){if(!db){toast('보관함을 아직 열지 못했습니다. 새로고침해 주세요.');return}let added=0,duplicates=0,failed=0;const candidates=[...files];toast('음악을 기기에 저장하는 중…');for(const file of candidates){if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|ogg|flac|aac|aiff|opus)$/i.test(file.name)){failed++;continue}if(tracks.some(t=>t.filename===file.name&&t.blob.size===file.size)){duplicates++;continue}try{const duration=await metadata(file),name=file.name.replace(/\.[^.]+$/,'');const parts=name.split(' - ');const t={id:crypto.randomUUID(),title:parts.length>1?parts.slice(1).join(' - '):name,artist:parts.length>1?parts[0]:'나의 음악',filename:file.name,blob:file,duration,added:Date.now(),favorite:false,color:['a','b','c'][tracks.length%3]};await persist(t);tracks.push(t);added++;render()}catch{failed++}}if(added&&navigator.storage?.persist)navigator.storage.persist().catch(()=>{});toast([added?`${added}곡을 소장했습니다`:'',duplicates?`중복 ${duplicates}곡 건너뜀`:'',failed?`${failed}개 저장 실패 · 파일 형식과 여유 공간을 확인해 주세요`:'' ].filter(Boolean).join(' · ')||'추가할 파일이 없습니다');$('#files').value=''}
['add-top','add-small','add-empty','mobile-add'].forEach(id=>$('#'+id).onclick=()=>$('#files').click());$('#files').onchange=e=>importFiles(e.target.files);document.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('dragging')});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('dragging')});document.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('dragging');importFiles(e.dataTransfer.files)});
$('#load-demo').onclick=async()=>{const button=$('#load-demo');button.disabled=true;try{const response=await fetch('sample.wav');if(!response.ok)throw Error();const blob=await response.blob();const track={id:crypto.randomUUID(),title:'초록빛 오후',artist:'소장 스튜디오',filename:'sojang-sample.wav',blob,duration:18,added:Date.now(),favorite:false,color:'a',demo:true};await persist(track);tracks.push(track);render();selectTrack(track.id,false);toast('직접 합성한 18초 예시 음악입니다. 재생을 눌러보세요.')}catch{toast('예시 음악을 가져오지 못했습니다. 인터넷 연결을 확인해 주세요.')}finally{button.disabled=false}};
function manageTrack(t){showDialog(`<div class="eyebrow muted">TRACK DETAILS</div><h2>음악 관리</h2><form id="edit-form"><label class="form-label">곡 제목<input id="edit-title" value="${escapeHTML(t.title)}" required maxlength="120"></label><label class="form-label">아티스트<input id="edit-artist" value="${escapeHTML(t.artist)}" required maxlength="100"></label><label class="form-label">앨범 이미지<input id="edit-cover" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="dialog-row"><span>파일 크기</span>${formatSize(t.blob.size)}</div><div class="dialog-actions"><button type="button" id="delete-track" class="text-button">곡 삭제</button><button class="primary" type="submit">저장</button></div></form>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();const copy={...t,title:$('#edit-title').value.trim(),artist:$('#edit-artist').value.trim()};if(!copy.title||!copy.artist)return;try{const file=$('#edit-cover').files[0];if(file)copy.cover=await resizeCover(file);await persist(copy);Object.assign(t,copy);render();if(current?.id===t.id&&'mediaSession'in navigator)navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist});$('#dialog').close();toast('곡 정보를 저장했습니다')}catch{toast('저장하지 못했습니다. 이미지 형식과 여유 공간을 확인해 주세요.')}};$('#delete-track').onclick=()=>{showDialog(`<h2>이 곡을 삭제할까요?</h2><p>‘${escapeHTML(t.title)}’이 소장 보관함에서 삭제됩니다. 원본 음악 파일은 그대로 유지됩니다.</p><div class="dialog-actions"><button class="text-button" id="cancel-delete">취소</button><button class="primary danger" id="confirm-delete">삭제</button></div>`);$('#cancel-delete').onclick=()=>$('#dialog').close();$('#confirm-delete').onclick=async()=>{try{await transaction('readwrite',s=>s.delete(t.id));if(current?.id===t.id){audio.pause();audio.removeAttribute('src');audio.load();if(url)URL.revokeObjectURL(url);url=null;current=null;$('#seek').value=0;$('#elapsed').textContent=$('#duration').textContent='0:00';if('mediaSession'in navigator)navigator.mediaSession.metadata=null}tracks=tracks.filter(x=>x.id!==t.id);render();$('#dialog').close();toast('보관함에서 삭제했습니다')}catch{toast('삭제하지 못했습니다. 다시 시도해 주세요.')}}}}
async function resizeCover(file){const img=new Image(),u=URL.createObjectURL(file);try{img.src=u;await img.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d'),size=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,512,512);return canvas.toDataURL('image/jpeg',.85)}finally{URL.revokeObjectURL(u)}}
async function settings(){const estimate=await navigator.storage?.estimate?.().catch(()=>null);showDialog(`<div class="eyebrow muted">YOUR PRIVATE COLLECTION</div><h2>나의 작은 음악 서랍</h2><p>소장은 직접 만든 음악 파일을 기기에 담아 듣는 개인용 플레이어입니다. 음악 파일과 앨범 이미지는 서버로 전송하지 않습니다.</p><div class="dialog-row"><span>보관 중인 음악</span>${tracks.length}곡</div><div class="dialog-row"><span>음악 파일 용량</span>${formatSize(tracks.reduce((n,t)=>n+t.blob.size,0))}</div>${estimate?`<div class="dialog-row"><span>이 사이트의 기기 저장 공간 사용량</span>${formatSize(estimate.usage||0)}</div>`:''}<div class="dialog-note">저장은 이 기기와 브라우저에만 적용됩니다. 다른 휴대폰이나 브라우저에는 음악이 자동으로 옮겨지지 않습니다. 브라우저 데이터 삭제·앱 제거·기기 저장 공간 부족으로 보관함이 사라질 수 있으니 원본 파일은 따로 보관하세요.<br><br>오프라인 실행은 첫 접속과 앱 준비가 완료된 뒤 가능합니다. 잠금 화면·백그라운드 재생은 휴대폰과 브라우저에 따라 중단될 수 있습니다. MP3와 M4A를 권장하며 지원 형식은 기기에 따라 달라집니다.</div><p>디자인·기능 참고: <span class="ref-links"><a href="https://apps.apple.com/us/app/doppler-mp3-flac-player/id1468459747" target="_blank" rel="noopener">Doppler</a> · <a href="https://doppi.app/" target="_blank" rel="noopener">Doppi</a></span></p><button class="primary" id="guide-install">홈 화면에 추가하는 방법</button>`);$('#guide-install').onclick=install}
