async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return}showDialog(`<div class="eyebrow muted">TAKE YOUR SOUND WITH YOU</div><h2>내 폰에 소장하기</h2><p>설치 파일 없이 홈 화면에서 앱처럼 열 수 있어요.</p><ol><li><strong>아이폰</strong>: Safari로 이 주소를 열고, 공유 버튼 → ‘홈 화면에 추가’를 선택하세요.</li><li><strong>안드로이드</strong>: Chrome 메뉴(⋮) → ‘홈 화면에 추가’ 또는 ‘앱 설치’를 선택하세요.</li><li>홈 화면의 소장을 열고 ‘음악 가져오기’로 내 파일을 추가하세요.</li></ol><div class="dialog-note">개인용 주소이므로 처음에는 본인의 ChatGPT 계정으로 로그인해야 합니다. 실제 폰에서 음악 한 곡을 추가한 뒤 비행기 모드와 잠금 화면 재생도 확인해 주세요.<br><br>앱 저장 데이터는 브라우저 환경에 따라 다를 수 있으므로 홈 화면에 추가한 후 음악을 가져오는 것을 권장합니다.</div>`)}
$('#install').onclick=install;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#open-player').onclick=$('#open-player-info').onclick=()=>document.body.classList.add('player-open');$('#close-player').onclick=()=>document.body.classList.remove('player-open');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('player-open');if(e.code==='Space'&&!/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)&&!$('#dialog').open){e.preventDefault();togglePlay()}});
if('mediaSession'in navigator){for(const [key,fn] of Object.entries({play:()=>selectTrack(current?.id||visible()[0]?.id),pause:()=>audio.pause(),previoustrack:()=>advance(-1),nexttrack:()=>advance(1),seekto:e=>{if(Number.isFinite(e.seekTime))audio.currentTime=e.seekTime},seekbackward:e=>audio.currentTime=Math.max(0,audio.currentTime-(e.seekOffset||10)),seekforward:e=>audio.currentTime=Math.min(audio.duration||0,audio.currentTime+(e.seekOffset||10))})){try{navigator.mediaSession.setActionHandler(key,fn)}catch{}}}
(async()=>{try{db=await openDB();tracks=await transaction('readonly',s=>s.getAll());render();if(tracks.length)await selectTrack(visible()[0].id,false)}catch{render();toast('기기 저장 공간을 열지 못했습니다. 일반 브라우저에서 다시 열어 주세요.')}if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>toast('오프라인 준비에 실패했습니다. 인터넷 연결을 유지해 주세요.'))})();
if(/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)){const volume=document.querySelector('.volume');volume.innerHTML='<span aria-hidden="true">◖))</span><span style="font-size:10px;line-height:1.7">음량은 아이폰 옆면 버튼으로 조절하세요</span>';volume.style.justifyContent='center';}
